mapper.select:
  select t.*,info.parent_portfolio_id parentId,
        rn
from (
/* 子查询必加上rn字段 */
SELECT result.* FROM (
SELECT tmp.*,
@rownum := @rownum + 1 row, /* 虚拟列行标 */
IF(
(
@portfolio_id = tmp.portfolio_id and
@profit_type = tmp.profit_type
),
@rank := @rank + 1,
@rank := 1
) AS rn, /* 分组虚拟列行标 */
/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
@portfolio_id := tmp.portfolio_id /* 分组条件1 */
, @profit_type := tmp.profit_type /* 分组条件2 */
FROM (
/* 数据源 */
SELECT bc.*
FROM PL_TARGET_DB bc
ORDER BY t.cdate asc /* 按实际情况与oracle保持一至的排序 */
) tmp,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@portfolio_id := null,
@profit_type = null,
@rank := 0) a
) result
) t
  left join PTL_PORTFOLIO info on info.portfolio_id = t.portfolio_id
  where 1 = 1

   and t.cdate >= #{searchDateStart,jdbcType=DATE}


   and t.cdate <= #{searchDateEnd,jdbcType=DATE}


   and t.portfolio_id = #{portfolioId}

		select t2.*,info.parent_portfolio_id parentId from (
		  select t1.*
		     from (
		         select t.*,
		                rn
		from (
		/* 子查询必加上rn字段 */
		SELECT result.* FROM (
		SELECT tmp.*,
		@rownum := @rownum + 1 row, /* 虚拟列行标 */
		IF(
		(
		@portfolio_id = tmp.portfolio_id and
		@profit_type = tmp.profit_type
		),
		@rank := @rank + 1,
		@rank := 1
		) AS rn, /* 分组虚拟列行标 */
		/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
		@portfolio_id := tmp.portfolio_id /* 分组条件1 */
		, @profit_type := tmp.profit_type /* 分组条件2 */
		FROM (
		/* 数据源 */
		SELECT bc.*
		FROM PL_TARGET_DB bc
		ORDER BY t.cdate desc /* 按实际情况与oracle保持一至的排序 */
		) tmp,
		/* 定义临时变量池 */
		(SELECT @rownum := 0,
		@portfolio_id := null,
		@profit_type = null,
		@rank := 0) a
		) result
		) t
		          where 1 = 1
		         and t.PORTFOLIO_ID in (select a.portfolio_id from (

		select portfolio_id from PTL_PORTFOLIO where 1 = 1

			AND portfolio_id in

				#{portfolioId}


		union

		select portfolio_id from PTL_PORTFOLIO where 1 = 1

			AND parent_portfolio_id in

				#{portfolioId}


		) a)

		           and t.cdate >= #{searchDateStart,jdbcType=DATE}


		           and t.cdate <= #{searchDateEnd,jdbcType=DATE}

		    ) t1
		where rn = 1 ) t2 
		left join PTL_PORTFOLIO info on info.portfolio_id = t2.portfolio_id
		where 1 = 1

		 	and t2.profit_type in 

                    #{profitType}



			AND t2.portfolio_id in (
				select portfolio_id from PTL_PORTFOLIO_AUTHORITY where user_id IN

				#{item}

			)

select t2.*,info.parent_portfolio_id parentId from (
  select t1.*
     from (
         select t.*,
                rn
from (
/* 子查询必加上rn字段 */
SELECT result.* FROM (
SELECT tmp.*,
@rownum := @rownum + 1 row, /* 虚拟列行标 */
IF(
(
@portfolio_id = tmp.portfolio_id and
@profit_type = tmp.profit_type
),
@rank := @rank + 1,
@rank := 1
) AS rn, /* 分组虚拟列行标 */
/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
@portfolio_id := tmp.portfolio_id /* 分组条件1 */
, @profit_type := tmp.profit_type /* 分组条件2 */
FROM (
/* 数据源 */
SELECT bc.*
FROM PL_TARGET_DB bc
ORDER BY t.cdate desc /* 按实际情况与oracle保持一至的排序 */
) tmp,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@portfolio_id := null,
@profit_type = null,
@rank := 0) a
) result
) t
          where 1 = 1
         and t.PORTFOLIO_ID in (select a.portfolio_id from (
select portfolio_id from PTL_PORTFOLIO where 1 = 1
) a)
    ) t1
where rn = 1 ) t2 
left join PTL_PORTFOLIO info on info.portfolio_id = t2.portfolio_id
where 1 = 1

	  select
	  	#{startDate,jdbcType=DATE} cdate,
	  	yield
	  from (
		  select
		    EFF_DATE,
		    t.INT_RATE yield 
		  from MST_INT_RATE_INFO t 
		  where
		    t.INT_RATE != null

		      AND #{startDate,jdbcType=DATE} >= EFF_DATE


			   AND INT_RATE_ID = #{IntRateId}


               AND INT_RATE_TYPE = #{IntRateType}

           order by EFF_DATE desc	  
	  ) where LIMIT 1
	  union all
	  select datas as cdate, T2.INT_RATE as yield
	  from (
	set @startDate = str_to_date(#{startDate,jdbcType=DATE}, '%Y-%m-%d');
	set @endDate = str_to_date(#{endDate,jdbcType=DATE}, '%Y-%m-%d');
	select t.DATAS AS DATAS from (
	select
	DATE_ADD(t.MINDATE, INTERVAL (if(@rownum=0, 0, @rownum)) DAY) GDATE, @rownum := @rownum +1 AS rownum
	from (
	select * from (SELECT @endDate MAXDATE,
	@startDate MINDATE,
	to_days(@endDate) - to_days(@startDate) days
	FROM dual) a,
	(SELECT @rownum:= 1) r) t
	left join connect_by_key cbk on cbk.num <=t.days
	) t






	) t1
	  left join (select t.INT_RATE, t.EFF_DATE
	               from MST_INT_RATE_INFO t


			                AND EFF_DATE >= #{startDate,jdbcType=DATE}


			                AND #{endDate,jdbcType=DATE} >= EFF_DATE


			                AND INT_RATE_ID = #{IntRateId}


			                AND INT_RATE_TYPE = #{IntRateType}


			 ) T2
	    on T2.EFF_DATE = t1.datas

      select
	  	#{startDate,jdbcType=DATE} cdate,
	  	yield
	  from (
		  select
		    CURVE_DATE,
		    t.YIELD yield 
		  from MST_YIELD_CURVE_INFO t 
		  where
		    t.YIELD != null

		      AND #{startDate,jdbcType=DATE} >= CURVE_DATE


                AND CURVE_CODE = #{curveCode}

           order by CURVE_DATE desc	  
	  ) where LIMIT 1
	  union all
	  select datas as cdate, T2.YIELD as yield
	  from (
	set @startDate = str_to_date(#{startDate,jdbcType=DATE}, '%Y-%m-%d');
	set @endDate = str_to_date(#{endDate,jdbcType=DATE}, '%Y-%m-%d');
	select t.DATAS AS DATAS from (
	select
	DATE_ADD(t.MINDATE, INTERVAL (if(@rownum=0, 0, @rownum)) DAY) GDATE, @rownum := @rownum +1 AS rownum
	from (
	select * from (SELECT @endDate MAXDATE,
	@startDate MINDATE,
	to_days(@endDate) - to_days(@startDate) days
	FROM dual) a,
	(SELECT @rownum:= 1) r) t
	left join connect_by_key cbk on cbk.num <=t.days
	) t





	) t1
	  left join (select t.YIELD, t.CURVE_DATE
	               from MST_YIELD_CURVE_INFO t


			                AND CURVE_DATE >= #{startDate,jdbcType=DATE}


			                AND #{endDate,jdbcType=DATE} >= CURVE_DATE


			                AND CURVE_CODE = #{curveCode}


			 ) T2
	    on T2.CURVE_DATE = t1.datas

	  select
	  	#{startDate,jdbcType=DATE} cdate,
	  	yield
	  from (
		  select
		    EFF_DATE,
		    t.CLOSE_PRICE yield 
		  from MST_EXPONENT_QUOTATION t 
		  where
		    t.INT_RATE != null

		      AND #{startDate,jdbcType=DATE} >= EFF_DATE


			   AND MARKET_ID = #{marketId}

           order by EFF_DATE desc	  
	  ) where LIMIT 1
	  union all
	  select datas as cdate, T2.CLOSE_PRICE as yield
	  from (
	set @startDate = str_to_date(#{startDate,jdbcType=DATE}, '%Y-%m-%d');
	set @endDate = str_to_date(#{endDate,jdbcType=DATE}, '%Y-%m-%d');
	select t.DATAS AS DATAS from (
	select
	DATE_ADD(t.MINDATE, INTERVAL (if(@rownum=0, 0, @rownum)) DAY) GDATE, @rownum := @rownum +1 AS rownum
	from (
	select * from (SELECT @endDate MAXDATE,
	@startDate MINDATE,
	to_days(@endDate) - to_days(@startDate) days
	FROM dual) a,
	(SELECT @rownum:= 1) r) t
	left join connect_by_key cbk on cbk.num <=t.days
	) t





	) t1
	  left join (select t.CLOSE_PRICE, t.EFF_DATE
	               from MST_INT_RATE_INFO t


			                AND EFF_DATE >= #{startDate,jdbcType=DATE}


			                AND #{endDate,jdbcType=DATE} >= EFF_DATE


							AND MARKET_ID = #{marketId}


			 ) T2
	    on T2.EFF_DATE = t1.datas

  select datas as cdate, T2.int_rate as yield
  from (
set @startDate = str_to_date(#{startDate,jdbcType=DATE}, '%Y-%m-%d');
set @endDate = str_to_date(#{endDate,jdbcType=DATE}, '%Y-%m-%d');
select t.DATAS from (
select
DATE_ADD(t.MINDATE, INTERVAL (if(@rownum=0, 0, @rownum)) DAY) GDATE, @rownum := @rownum +1 AS rownum
from (
select * from (SELECT @endDate MAXDATE,
@startDate MINDATE,
to_days(@endDate) - to_days(@startDate) days
FROM dual) a,
(SELECT @rownum:= 1) r) t
left join connect_by_key cbk on cbk.num <=t.days
) t ) t1
  left join (select t.int_rate, t.eff_date
               from MST_INT_RATE_INFO t


		                AND EFF_DATE >= #{startDate,jdbcType=DATE}


		                AND #{endDate,jdbcType=DATE} >= EFF_DATE


		                AND INT_RATE_TYPE = #{intRateType}


		                AND INT_RATE_ID = #{intRateId}


		 ) T2
    on T2.eff_date = t1.datas
